/*
Polyglot Rust/C++ Fibonacci calculator
- Compile as Rust: rustc /app/polyglot/main.rs && /app/polyglot/main N
- Compile as C++:  g++ -x c++ /app/polyglot/main.rs -o /app/polyglot/cmain && /app/polyglot/cmain N
*/

#ifdef __cplusplus
#include <iostream>
#include <cstdlib>
using namespace std;

int fib(int n) {
    return n <= 1 ? 1 : fib(n - 1) + fib(n - 2);
}

int main(int argc, char** argv) {
    int n = argc > 1 ? atoi(argv[1]) : 0;
    cout << fib(n) << endl;
    return 0;
}
#else

fn fib(n: i32) -> i32 {
    if n <= 1 { 1 } else { fib(n - 1) + fib(n - 2) }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let n: i32 = args.get(1).and_then(|s| s.parse().ok()).unwrap_or(0);
    println!("{}", fib(n));
}
#endif

